-- Canonical SYNTH FO4 core actions.
-- Keep this list in sync with synthCanonicalActionCodes() in functions/functions.php.

DELETE FROM synth.core_action
WHERE metadata @> '{"source":"functions.php","builtin":true}'::jsonb
  AND code_name NOT IN (
    'Attack',
    'CheckInventory',
    'ComeCloser',
    'Consume',
    'EquipItem',
    'DecreaseWalkSpeed',
    'EndConversation',
    'Follow',
    'FollowPlayer',
    'StopFollowing',
    'GiveCapsTo',
    'GiveItemTo',
    'IncreaseWalkSpeed',
    'Inspect',
    'InspectSurroundings',
    'MakeFollower',
    'MoveTo',
    'Barter',
    'OpenInventory',
    'PickupItem',
    'ReadQuests',
    'ReleaseWait',
    'Relax',
    'DirectorCommand',
    'SpawnCaps',
    'SpawnItem',
    'TeleportActor',
    'KillTarget',
    'SheatheWeapon',
    'StopWalk',
    'TakeASeat',
    'TakeCapsFromPlayer',
    'TravelTo',
    'UnequipItem',
    'WaitHere'
  );

