INSERT INTO synth.core_action (
    code_name,
    action_name,
    description,
    return_message,
    available_to_npc,
    available_to_followers,
    available_to_narrator,
    is_activated,
    parameters_json,
    metadata,
    game_function,
    import_version,
    script_proxy_program
) VALUES
    ('ReleaseWait', 'ReleaseWait', 'Release #SYNTH_NAME# from SYNTH waiting. This does not recruit a follower.', '#SYNTH_NAME# is released from SYNTH waiting.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{},"additionalProperties":false}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('Attack', 'Attack', 'Attack a target actor or entity.', '#SYNTH_NAME# attacks #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"Target NPC, actor, or being."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('CheckInventory', 'Check_Inventory', 'Search #SYNTH_NAME#''s inventory and list contents.', '#SYNTH_NAME#''s INVENTORY:#RESULT#', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Optional item to look for. Leave blank to list all items."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"enabled":true,"arg_name":"target","prompt":"Reply with one short in-character line about the inventory result below. Do not ask follow-up questions."}}'::jsonb, TRUE, 0, NULL),
    ('ComeCloser', 'Come_Closer', '#SYNTH_NAME# approaches #PLAYER_NAME#.', '#SYNTH_NAME# approaches #PLAYER_NAME#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","cooldown_seconds":30}'::jsonb, TRUE, 0, NULL),
    ('Consume', 'Consume', '#SYNTH_NAME# consumes food, drink, chems, or another aid item from inventory.', '#SYNTH_NAME# consumes an item from inventory.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"Exact inventory item name to consume."},"item":{"type":"string","description":"Optional fallback copy of the same item name."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('EquipItem', 'Equip_Item', '#SYNTH_NAME# equips a weapon or wearable item already present in inventory.', '#SYNTH_NAME# equips #ITEM#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["item"],"properties":{"item":{"type":"string","description":"Exact weapon or wearable item name from inventory."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('DecreaseWalkSpeed', 'Decrease_Walk_Speed', 'Decrease #SYNTH_NAME#''s movement speed.', 'Decreases #SYNTH_NAME#''s speed or pace.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"speed":{"type":"string","enum":["jog","walk"],"description":"Requested pace."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('EndConversation', 'End_Conversation', '#SYNTH_NAME# ends the conversation for a short time.', '#SYNTH_NAME# ends the conversation.', TRUE, FALSE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('Follow', 'Follow', 'Move to and follow the specified target actor.', '#SYNTH_NAME# follows #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"Target NPC, actor, or being to follow."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","cooldown_seconds":30}'::jsonb, TRUE, 0, NULL),
    ('FollowPlayer', 'Follow_#PLAYER_NAME#', '#SYNTH_NAME# follows #PLAYER_NAME#.', '#SYNTH_NAME# follows #PLAYER_NAME#.', TRUE, FALSE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","cooldown_seconds":30}'::jsonb, TRUE, 0, NULL),
    ('StopFollowing', 'Stop_Following_#PLAYER_NAME#', '#SYNTH_NAME# stops following #PLAYER_NAME# and leaves the current follower role.', '#SYNTH_NAME# stops following #PLAYER_NAME#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","cooldown_seconds":30,"followup":{"enabled":false}}'::jsonb, TRUE, 0, NULL),
    ('GiveCapsTo', 'Give_Caps_To', '#SYNTH_NAME# gives caps to another actor or #PLAYER_NAME#.', '#SYNTH_NAME# gives #AMOUNT# caps to #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"Recipient actor or #PLAYER_NAME#."},"amount":{"type":"integer","description":"Caps amount to give."},"item":{"type":"string","description":"Optional amount fallback as text."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('GiveItemTo', 'Give_Item_To', '#SYNTH_NAME# gives a specific item from inventory to another actor or #PLAYER_NAME#.', '#SYNTH_NAME# gives #ITEM# to #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target","item"],"properties":{"target":{"type":"string","description":"Recipient actor or #PLAYER_NAME#."},"item":{"type":"string","description":"Exact inventory item name."},"amount":{"type":"integer","description":"Quantity to give, default 1."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('IncreaseWalkSpeed', 'Increase_Walk_Speed', 'Increase #SYNTH_NAME#''s movement speed.', 'Increases #SYNTH_NAME#''s speed or pace.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"speed":{"type":"string","enum":["run","jog"],"description":"Requested pace."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('Inspect', 'Inspect', 'Inspect a nearby actor or being.', '#SYNTH_NAME# inspects #TARGET# and sees this: #RESULT#', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"Nearby NPC, actor, or being to inspect."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"enabled":true,"arg_name":"target","prompt":"Reply with one short in-character observation using the inspect result below. Do not ask follow-up questions."}}'::jsonb, TRUE, 0, NULL),
    ('InspectSurroundings', 'Inspect_Surroundings', 'Look around and assess nearby people, items, doors, and threats.', '#SYNTH_NAME# takes a look around and sees this: #RESULT#', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"enabled":true,"arg_name":"target","prompt":"Reply with one short in-character observation about the surroundings using the tool result below. Do not ask follow-up questions."}}'::jsonb, TRUE, 0, NULL),
    ('MakeFollower', 'Join_#PLAYER_NAME#_Party', '#SYNTH_NAME# joins #PLAYER_NAME# as a follower.', '#SYNTH_NAME# is now part of the adventuring party.', TRUE, FALSE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('MoveTo', 'Move_To', 'Move to a visible nearby actor or NPC. Use TravelTo for places.', '#SYNTH_NAME# moves to #TARGET#.', TRUE, FALSE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"Visible nearby actor or NPC."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('Barter', 'Barter', 'Open a vendor-style barter menu with #SYNTH_NAME# when #SYNTH_NAME# has merchant inventory or an active service package. If no merchant inventory is available, this falls back to regular item trade.', 'Opens merchant barter with #SYNTH_NAME# when available, otherwise opens regular item trade.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","suppress_placeholder_infoaction":true}'::jsonb, TRUE, 0, NULL),
    ('OpenInventory', 'Open_Inventory', 'Open #SYNTH_NAME#''s inventory for free item exchange with #PLAYER_NAME#.', 'Opens #SYNTH_NAME#''s inventory for item exchange with #PLAYER_NAME#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","suppress_placeholder_infoaction":true}'::jsonb, TRUE, 0, NULL),
    ('PickupItem', 'Pickup_Item', '#SYNTH_NAME# picks up a nearby item from the ground.', '#SYNTH_NAME# picks up #ITEM#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["item"],"properties":{"item":{"type":"string","description":"Exact nearby RefID:ItemName."},"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('ReadQuests', 'Read_Quests', 'Read the quest log and get information about current quests.', '', TRUE, TRUE, TRUE, TRUE, '{"type":"object","required":[],"properties":{"id_quest":{"type":"string","description":"Optional specific quest id or name."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"enabled":true,"arg_name":"id_quest","prompt":"Reply with one short in-character line about the quest result below. Do not ask follow-up questions."}}'::jsonb, TRUE, 0, NULL),
    ('Relax', 'Relax', '#SYNTH_NAME# relaxes at the current location without being dismissed.', '#SYNTH_NAME# relaxes at the current location.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{},"additionalProperties":false}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('DirectorCommand', 'Director_Command', 'Send a short freeform instruction to the game director so it can stage a scene or event.', 'The director is preparing a scene instruction.', FALSE, FALSE, TRUE, FALSE, '{"type":"object","required":["instruction"],"properties":{"instruction":{"type":"string","description":"Short freeform director brief describing the scene instruction or event to stage."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"server_action"}'::jsonb, FALSE, 0, NULL),
    ('SpawnCaps', 'Spawn_Caps', 'Create caps and give them to #PLAYER_NAME# or another nearby actor.', '#TARGET# receives #AMOUNT# caps.', FALSE, FALSE, TRUE, FALSE, '{"type":"object","required":["amount"],"properties":{"target":{"type":"string","description":"Recipient actor. Leave blank to give the caps to #PLAYER_NAME#."},"amount":{"type":"integer","description":"Positive caps amount, maximum 1000000."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('SpawnItem', 'Spawn_Item', 'Create a named item from the descriptions database and give it to #PLAYER_NAME# or another nearby actor.', '#TARGET# receives #ITEM#.', FALSE, FALSE, TRUE, FALSE, '{"type":"object","required":["item"],"properties":{"target":{"type":"string","description":"Recipient actor. Leave blank to give the item to #PLAYER_NAME#."},"item":{"type":"string","description":"Item name from the descriptions database."},"amount":{"type":"integer","description":"Quantity to create, default 1 and maximum 100."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('TeleportActor', 'Teleport_Actor', 'Teleport #PLAYER_NAME# or another nearby actor to a named synchronized location.', '#TARGET# teleports to #LOCATION#.', FALSE, FALSE, TRUE, FALSE, '{"type":"object","required":["location"],"properties":{"target":{"type":"string","description":"Actor to teleport. Leave blank to teleport #PLAYER_NAME#."},"location":{"type":"string","description":"Destination from the synchronized Fallout location database."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('KillTarget', 'Kill_Target', 'Kill a chosen nearby actor immediately.', '#TARGET# is killed.', FALSE, FALSE, TRUE, FALSE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"Nearby actor to kill, including #PLAYER_NAME# when explicitly requested."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('SheatheWeapon', 'Sheathe_Weapon', 'Sheathe or put away the current weapon.', 'Sheathes/put away current weapon', FALSE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('StopWalk', 'Stop_Walk', 'Stop all of #SYNTH_NAME#''s movement or travel actions.', 'Stop all of #SYNTH_NAME#''s actions immediately.', FALSE, FALSE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('TakeASeat', 'Take_A_Seat', '#SYNTH_NAME# takes a seat at a nearby seating location.', '#SYNTH_NAME# sits in a nearby chair or piece of furniture.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('TakeCapsFromPlayer', 'Take_Caps_From_#PLAYER_NAME#', '#SYNTH_NAME# takes caps from #PLAYER_NAME# once #PLAYER_NAME# agrees.', '#PLAYER_NAME# gave #TARGET# caps to #SYNTH_NAME#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["amount"],"properties":{"amount":{"type":"integer","description":"Caps amount to take from #PLAYER_NAME#."},"target":{"type":"string","description":"Optional reason or transaction target."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('TravelTo', 'Travel_To', 'Travel long distance to a building, city, door, or other location.', '#SYNTH_NAME# begins travelling to #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["location"],"properties":{"location":{"type":"string","description":"Building, city, door, or other location."},"target":{"type":"string","description":"Optional destination fallback. If used, the server treats it as location."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('UnequipItem', 'Unequip_Item', '#SYNTH_NAME# removes a currently equipped weapon or wearable item.', '#SYNTH_NAME# removes #ITEM#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["item"],"properties":{"item":{"type":"string","description":"Exact currently equipped weapon or wearable item name from inventory."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('WaitHere', 'Wait_Here', '#SYNTH_NAME# waits at the current location.', '#SYNTH_NAME# waits and stands at the place.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep blank."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","cooldown_seconds":30}'::jsonb, TRUE, 0, NULL)
ON CONFLICT (code_name) DO UPDATE SET
    action_name = EXCLUDED.action_name,
    description = EXCLUDED.description,
    return_message = EXCLUDED.return_message,
    available_to_npc = EXCLUDED.available_to_npc,
    available_to_followers = EXCLUDED.available_to_followers,
    available_to_narrator = EXCLUDED.available_to_narrator,
    is_activated = EXCLUDED.is_activated,
    parameters_json = EXCLUDED.parameters_json,
    metadata = EXCLUDED.metadata,
    game_function = EXCLUDED.game_function,
    import_version = EXCLUDED.import_version,
    script_proxy_program = EXCLUDED.script_proxy_program,
    updated_at = NOW();
